custom_css:
@import url('/css/tavernnext-atelier.css');

:root {
    --tn-accent: #a7cdb0;
    --tn-accent-hover: #bbd9c1;
    --tn-accent-soft: rgba(167, 205, 176, 0.16);
    --tn-accent-fill: #b9d8bf;
    --tn-accent-fill-hover: #c7e1cc;
    --tn-accent-contrast: #17231a;
    --tn-accent-border: #8eb397;
    --tn-accent-highlight: rgba(255, 255, 255, 0.36);
    --tn-accent-shadow: rgba(0, 0, 0, 0.3);
    --tn-status-contrast: #111311;
    --tn-surface-0: rgba(21, 22, 21, 0.97);
    --tn-surface-1: rgba(29, 30, 29, 0.97);
    --tn-surface-2: rgba(37, 39, 37, 0.96);
    --tn-surface-solid: #1d1e1d;
    --tn-field: rgba(18, 19, 18, 0.96);
    --tn-field-hover: #171917;
    --tn-field-highlight: rgba(255, 255, 255, 0.04);
    --tn-hover: rgba(167, 205, 176, 0.1);
    --tn-active: rgba(167, 205, 176, 0.18);
    --tn-selected: rgba(167, 205, 176, 0.14);
    --tn-hairline: rgba(224, 229, 225, 0.1);
    --tn-code-bg: #101110;
    --tn-code-text: #dde1dd;
    --tn-danger: #e18391;
    --tn-success: #9bc7a5;
    --tn-warning: #d7b879;
    --tn-scrollbar: rgba(224, 229, 225, 0.22);
    --tn-shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.24), 0 6px 18px rgba(0, 0, 0, 0.18);
    --tn-shadow-lg: 0 16px 40px rgba(0, 0, 0, 0.46);
}

body { color-scheme: dark !important; }
